 function renderFractionGlyphs(value: string): ReactNode {
   const parts: ReactNode[] = [];
   let previousIndex = 0;
   for (const match of value.matchAll(/½|⅓|⅔|¼|¾|⅛|⅜|⅝|⅞/gu)) {
     const index = match.index ?? 0;
     if (index > previousIndex) {
